import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';

// Force logged-out state on every page load (user + admin).
// Keeps non-auth settings (e.g., theme) intact.
localStorage.removeItem('token');
localStorage.removeItem('user');
localStorage.removeItem('adminToken');
localStorage.removeItem('adminUser');
// Notify any listeners (admin panel uses this for cross-tab sync).
window.dispatchEvent(new Event('adminAuthChange'));

// Apply saved theme on initial load
const savedTheme = localStorage.getItem('theme');
if (savedTheme === 'dark') {
  document.documentElement.classList.add('dark');
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

// Basic PWA service worker registration (offline cache)
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js').catch((err) => {
      // Keep silent in production; console is fine for dev
      console.log('SW registration failed:', err);
    });
  });
}
